(1029,'EU INSPIRE identifier','Identifiers defined in EU INSPIRE specification for CRS, 2009-06-29','OGP','OGP','2010-02-19','2010.003',false),
(1030,'Finland alternative identifier','An alternative name used in Finland, following the style of the EU INSPIRE identifier.','OGP','OGP','2010-03-20','2008.112',false),
(1031,'Petrobras alternative identifier','Identifier used in Brazil by Petrobras','OGP','OGP','2010-03-25','2010.039',false),
