(1035,'Brazil alternative identifier','An alternative name used in Brazil.','OGP','OGP','2011-07-23','2011.053',false),
(1036,'Algeria alternative identifier','An alternative name used by INCT.','OGP','OGP','2012-03-20','2011.111',false),
(1037,'Cyprus alternative identifier','','IOGP','IOGP','2015-04-02','2014.091',false),
(1038,'Albania alternative identifier','An alternative name used by ASIG.','OGP','OGP','2014-11-21','2014.008 2014.078',false),
(1039,'US DMA/NIMA/NGA code','Code used by the US National Geospatial Intelligence Agency.','OGP','OGP','2014-08-03','2014.037',false),
(1040,'Energistics name','A name assigned by Energistics in its Unit of Measure standard.','Energistics','IOGP','2015-11-21','2015.062',false),
(1041,'EPSG/Energistics abbreviation','A symbol assigned by Energistics in its Unit of Measure standard and used in the EPSG Dataset as an abbreviation.','IOGP','IOGP','2015-11-22','2015.062',false),
(1042,'Czech alternative identifier','An alternative name used in Czechia.','IOGP','IOGP','2019-05-17','2017.037 2019.030',false),
